MANIFEST_PATH = Path(__file__).parent / "../../plugin.yaml"
MANIFEST = load_manifest(MANIFEST_PATH.read_text())
# Not MANIFEST_PATH.parent: a manifest's shell/http-bodyFile relative paths
# are resolved against the plugin repository root, which can differ from
# the manifest file's own directory (examples/demo-app/plugin.yaml's own
# operations reach "examples/demo-app/cli.ts", rooted at the repo, not at
# examples/demo-app itself).
PLUGIN_ROOT = (Path(__file__).parent / "../..").resolve()

SCENARIO = json.loads("{\n  \"id\": \"SC-HUB-CASE-EDIT-LIFECYCLE\",\n  \"title\": \"editing a case's summary through the real case editor page persists to its file\",\n  \"preconditions\": [\n    \"suite.reachable\"\n  ],\n  \"steps\": [\n    {\n      \"id\": \"S-CREATE\",\n      \"summary\": \"a case exists to edit\",\n      \"action\": {\n        \"operation\": \"OP-CREATE-ENTITY\",\n        \"params\": {\n          \"entity\": {\n            \"id\": \"TC-HUB-EDIT-001\",\n            \"summary\": \"before the browser edit\",\n            \"baseline\": \"BL-HUB-PROBE\",\n            \"expect\": [\n              {\n                \"kind\": \"http_status\",\n                \"status\": 200\n              }\n            ]\n          },\n          \"kind\": \"case\"\n        }\n      },\n      \"expect\": [\n        {\n          \"kind\": \"http_status\",\n          \"status\": 200,\n          \"viewpoints\": [\n            \"VP-HUB-SAVE-VALID\"\n          ]\n        }\n      ],\n      \"polarity\": \"nominal\",\n      \"dependsOn\": [],\n      \"produces\": {},\n      \"viewpoints\": [\n        \"VP-HUB-SAVE-VALID\"\n      ]\n    },\n    {\n      \"id\": \"S-OPEN\",\n      \"summary\": \"the case editor page opens and shows the summary field\",\n      \"action\": {\n        \"operation\": \"OP-OPEN-CASE-EDITOR\",\n        \"params\": {\n          \"id\": \"TC-HUB-EDIT-001\"\n        }\n      },\n      \"expect\": [\n        {\n          \"kind\": \"text\",\n          \"value\": \"TC-HUB-EDIT-001\",\n          \"match\": \"contains\",\n          \"viewpoints\": [\n            \"VP-HUB-CASE-EDIT\"\n          ]\n        }\n      ],\n      \"polarity\": \"nominal\",\n      \"dependsOn\": [\n        \"S-CREATE\"\n      ],\n      \"produces\": {},\n      \"viewpoints\": [\n        \"VP-HUB-CASE-EDIT\"\n      ]\n    },\n    {\n      \"id\": \"S-EDIT-AND-SAVE\",\n      \"summary\": \"changing the summary and clicking Save completes without error\",\n      \"action\": {\n        \"operation\": \"OP-EDIT-CASE-SUMMARY\",\n        \"params\": {\n          \"id\": \"TC-HUB-EDIT-001\",\n          \"summary\": \"after the browser edit\"\n        }\n      },\n      \"expect\": [\n        {\n          \"kind\": \"text\",\n          \"value\": \"TC-HUB-EDIT-001\",\n          \"match\": \"contains\",\n          \"viewpoints\": [\n            \"VP-HUB-CASE-EDIT\"\n          ]\n        }\n      ],\n      \"polarity\": \"nominal\",\n      \"dependsOn\": [\n        \"S-OPEN\"\n      ],\n      \"produces\": {},\n      \"viewpoints\": [\n        \"VP-HUB-CASE-EDIT\"\n      ]\n    },\n    {\n      \"id\": \"S-CONFIRM-PERSISTED\",\n      \"summary\": \"the file on disk now holds the edited summary, not the original\",\n      \"action\": {\n        \"operation\": \"OP-GET-ENTITY\",\n        \"params\": {\n          \"id\": \"TC-HUB-EDIT-001\",\n          \"kind\": \"case\"\n        }\n      },\n      \"expect\": [\n        {\n          \"kind\": \"operation_result\",\n          \"operation\": \"OP-GET-ENTITY\",\n          \"params\": {\n            \"id\": \"TC-HUB-EDIT-001\",\n            \"kind\": \"case\"\n          },\n          \"assert\": {\n            \"kind\": \"contains\",\n            \"value\": \"after the browser edit\"\n          },\n          \"viewpoints\": [\n            \"VP-HUB-CASE-EDIT\"\n          ]\n        }\n      ],\n      \"polarity\": \"nominal\",\n      \"dependsOn\": [\n        \"S-EDIT-AND-SAVE\"\n      ],\n      \"produces\": {\n        \"expectedHash\": \"body.hash\"\n      },\n      \"viewpoints\": [\n        \"VP-HUB-CASE-EDIT\"\n      ]\n    },\n    {\n      \"id\": \"S-CLEANUP\",\n      \"summary\": \"the case is removed, leaving no trace for later runs\",\n      \"action\": {\n        \"operation\": \"OP-DELETE-ENTITY\",\n        \"params\": {\n          \"id\": \"TC-HUB-EDIT-001\",\n          \"kind\": \"case\"\n        }\n      },\n      \"expect\": [\n        {\n          \"kind\": \"http_status\",\n          \"status\": 200,\n          \"viewpoints\": [\n            \"VP-HUB-SAVE-VALID\"\n          ]\n        }\n      ],\n      \"polarity\": \"nominal\",\n      \"dependsOn\": [\n        \"S-CONFIRM-PERSISTED\"\n      ],\n      \"produces\": {},\n      \"viewpoints\": [\n        \"VP-HUB-SAVE-VALID\"\n      ]\n    }\n  ],\n  \"evidence\": {\n    \"sources\": [\n      \"screenshot\",\n      \"browser_console\",\n      \"browser_network\",\n      \"db_records\",\n      \"app_log\",\n      \"db_log\"\n    ],\n    \"timing\": \"after\",\n    \"trace\": \"on_failure\",\n    \"ignore\": []\n  },\n  \"evidenceWaivers\": [],\n  \"tags\": [\n    \"smoke\"\n  ],\n  \"viewpoints\": []\n}")


def test_sc_hub_case_edit_lifecycle() -> None:
    registry = ExecutorRegistry()
    registry.register(HttpExecutor())
    registry.register(ShellExecutor())
    registry.register(BrowserExecutor(PlaywrightDriver()))
    # A manifest's connections/operations commonly interpolate {{env.X}} (a
    # target URL, a token) — the operator supplies those as real environment
    # variables when running the generated test, so scopes["env"] defaults
    # to os.environ rather than being left empty.
    context = ExecutionContext(
        manifest=MANIFEST, scopes={"env": dict(os.environ)}, root=str(PLUGIN_ROOT)
    )
    result = run_scenario(SCENARIO, registry, context)
    assert result.verdict == "pass", result
